238	// required fields without launching any process.
239	func TestSweepDryRunCanaryPrints(t *testing.T) {
240		repoRoot := benchRepoRoot(t)
241		outDir := t.TempDir()
242	
243		old := os.Stdout
244		r, w, _ := os.Pipe()
245		os.Stdout = w
