260	
261		if code != 0 {
262			t.Fatalf("cmdSweep dry-run exit = %d, want 0\noutput:\n%s", code, output)
263		}
264	
265		// AC-1: print phases, lane ids, comparison_group ids, task count, reps,
266		// resource groups, max parallelism, and output directory.
267		required := []string{
268			"Phase: canary",
269			"Dataset:",
270			"Subset ID:",
271			"Task Count:",
272			"Reps:",
273			"Total Cells:",
274			"Output Dir:",
275			"Lane:",
276			"Profile:",
277			"Resource Group:",
278			"max_concurrency=",
279			"Comparison Groups:",
280			"Command:",
281		}
282		for _, want := range required {
283			if !strings.Contains(output, want) {
284				t.Errorf("dry-run output missing %q\nfull output:\n%s", want, output)
285			}
286		}
287	
288		// Verify at least one lane from canary is printed.
289		if !strings.Contains(output, "fiz-harness-claude-sonnet-4-6") {
290			t.Errorf("dry-run output missing canary lane fiz-harness-claude-sonnet-4-6")
291		}
292		// Verify the output directory appears.
293		if !strings.Contains(output, outDir) {
294			t.Errorf("dry-run output missing out dir %s", outDir)
295		}
