449	// TestSweepResourceGroupSchedulingSerializesLocalLanes uses a synthetic sweep
450	// plan with two lanes sharing a local resource group (max_concurrency=1) to
451	// verify they never run concurrently.
452	func TestSweepResourceGroupSchedulingSerializesLocalLanes(t *testing.T) {
453		// Build a minimal synthetic plan with one local resource group and two lanes.
454		plan := &sweepPlan{
455			Dataset:  "test",
456			Defaults: sweepDefaults{Reps: 1},
457			Phases: []sweepPhase{
458				{ID: "test-phase", Subset: "terminalbench-2-1-canary", Reps: 1,
459					Lanes: []string{"lane-a", "lane-b"}},
460			},
461			ResourceGroups: []sweepResourceGroup{
462				{ID: "rg-local", ProviderType: "local", MaxConcurrency: 1},
463			},
464			Lanes: []sweepLane{
465				{ID: "lane-a", ProfileID: "noop", ResourceGroup: "rg-local",
466					ModelFamily: "test", ModelID: "test", QuantLabel: "none",
467					LaneType: "fiz_provider_native", ProviderSurface: "local"},
468				{ID: "lane-b", ProfileID: "noop", ResourceGroup: "rg-local",
469					ModelFamily: "test", ModelID: "test", QuantLabel: "none",
470					LaneType: "fiz_provider_native", ProviderSurface: "local"},
471			},
472		}
473	
474		// Track peak concurrent executions within the resource group.
475		var (
476			mu             sync.Mutex
477			active         int
478			peakActive     int
479			completedLanes []string
480		)
481	
482		// Replace cmdMatrix with a counting mock via the resource group semaphore
483		// logic directly — test the scheduling structure, not actual matrix execution.
484		rgSems := make(map[string]chan struct{})
485		for _, rg := range plan.ResourceGroups {
486			cap := rg.MaxConcurrency
487			if cap < 1 {
488				cap = 1
489			}
490			rgSems[rg.ID] = make(chan struct{}, cap)
491		}
492	
493		laneByID := sweepLaneMap(plan)
494		rgByID := sweepRGMap(plan)
495	
496		outcomes := make([]sweepLaneOutcome, 2)
497		var wg sync.WaitGroup
498		var counter int64
499	
500		for i, laneID := range plan.Phases[0].Lanes {
501			lane := laneByID[laneID]
502			rg := rgByID[lane.ResourceGroup]
503			sem := rgSems[rg.ID]
504	
505			wg.Add(1)
506			go func(i int, lane *sweepLane, sem chan struct{}) {
507				defer wg.Done()
508				sem <- struct{}{}
509				defer func() { <-sem }()
510	
511				mu.Lock()
512				active++
513				if active > peakActive {
514					peakActive = active
515				}
516				mu.Unlock()
517	
518				// Simulate work: bump a counter and sleep briefly.
519				atomic.AddInt64(&counter, 1)
520				time.Sleep(10 * time.Millisecond)
521	
522				mu.Lock()
523				active--
524				completedLanes = append(completedLanes, lane.ID)
525				mu.Unlock()
526	
527				outcomes[i] = sweepLaneOutcome{laneID: lane.ID, code: 0}
528			}(i, lane, sem)
529		}
530		wg.Wait()
531	
532		if peakActive > 1 {
533			t.Errorf("local resource group (max_concurrency=1) had %d concurrent executions, want <= 1", peakActive)
534		}
535		if len(completedLanes) != 2 {
536			t.Errorf("completed %d lanes, want 2", len(completedLanes))
537		}
538	}
